"""Session lifecycle event composition handler."""

from __future__ import annotations

from typing import Callable, ClassVar, Optional

from rasa.core.channels.conversation_queue.queue import ConversationQueue
from rasa.core.voice.event_composition.events import (
    CompositeEvent,
    SessionEndedInteractionEvent,
    SessionStartedInteractionEvent,
)
from rasa.core.voice.event_composition.events.input_events import (
    LifecycleInputEvent,
    SessionEndedInputEvent,
    SessionStartedInputEvent,
)
from rasa.core.voice.event_composition.handlers.protocol import (
    RawEventTypes,
)


class LifecycleHandler:
    """Forward session lifecycle events as interaction events."""

    interested_in: ClassVar[RawEventTypes] = [
        SessionStartedInputEvent,
        SessionEndedInputEvent,
    ]

    def __init__(
        self,
        interaction_event_queue: ConversationQueue[CompositeEvent],
        on_session_ended: Optional[Callable[[], object]] = None,
    ) -> None:
        """Create a lifecycle handler.

        Args:
            interaction_event_queue: Queue the lifecycle interaction events go to.
            on_session_ended: Called as soon as the session ends, before the end
                event queues behind any turn still running, so that turn can stop.
        """
        self.interaction_event_queue = interaction_event_queue
        self._on_session_ended = on_session_ended

    async def handle(self, event: LifecycleInputEvent) -> None:
        """Handle session lifecycle events."""
        if isinstance(event, SessionStartedInputEvent):
            await self.interaction_event_queue.put(
                SessionStartedInteractionEvent(metadata=event.metadata)
            )
            return

        if isinstance(event, SessionEndedInputEvent):
            if self._on_session_ended is not None:
                self._on_session_ended()
            await self.interaction_event_queue.put(
                SessionEndedInteractionEvent(metadata=event.metadata)
            )
            return
